mapper.select:
SELECT USER_ID AS userId , USER_NM AS userNm , DEPT_NM AS deptNm , JOB_ROLE AS jobRole , POSITION_NM AS positionNm , CAREER_YEARS AS careerYears , CURRENT_LOAD AS currentLoad , JOIN_DT AS joinDt , AUTH_LEVEL AS authLevel , USE_YN AS useYn FROM TB_USER WHERE 1=1
AND USER_NM LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY JOIN_DT DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

mapper.insert:
